[Form]
public class FMSetup extends FormRun
{
    container imageContainer;
    FileUpload uploadControl;
    FileUpload accessoryUpload;

    //** Initial Positioning for FMVehicleModel Start
    FMVehicleModel startupFMVehicleModel;
    //** Initial Positioning for FMVehicleModel End
}

public void fillMakeForParent(int _idx, anytype _data)
{
    FMVehicleModel modelTable;
    FormTreeItem treeItem;

    while select Model, Make, RecId from modelTable order by Model where modelTable.Make == _data
    {
        // BP Deviation Documented
        treeItem = new FormTreeItem(modelTable.Model, 0, 0, modelTable.RecId);
        makeModelTree.addItem(_idx, 0, treeItem);
    }
}

public void init()
{
    SecurityRights rights;
    FMVehicleModel fmvm;

    super();

    rights = SecurityRights::construct();

    if (!rights.isSystemAdministrator())
    {
        ModuleSetup.visible(false);
    }

    //when uploading a vehicle model image, this method is called upon completion
    uploadControl = FileUpload1;
    uploadControl.notifyUploadCompleted +=  eventhandler(this.UploadCompleted);

    //when uploading an image for an accessory, this method is called upon completion.        
    accessoryUpload = ChargeImageUpload;
    accessoryUpload.notifyUploadCompleted +=  eventhandler(this.AccessoryUploadCompleted);        

    //** Initial Positioning for FMVehicleModel Start
    if(element.args().lookupTable() == tableNum(FMVehicleModel) &&
        element.args().lookupField() == fieldNum(FMVehicleModel, RecId))
    {
        select * from fmvm where fmvm.RecId == str2int64(element.args().lookupValue());
        if(fmvm)
        {
            element.args().lookupTable(tableNum(FMVehicleMake));
            element.args().lookupValue(int642str(fmvm.Make));

            startupFMVehicleModel = fmvm;
        }
    }
    //** Initial Positioning for FMVehicleModel End
}

private void loadMakes()
{
    FMVehicleMake   makeTable;

    FormTreeItem    treeItem;

    while select makeTable order by Make
    {
        // BP Deviation Documented
        treeItem = new FormTreeItem(makeTable.Make, 0, 1, makeTable.RecId);
        makeModelTree.addItem(0, 0, treeItem);
    }
    makeModelTree.selectEx(makeModelTree.getFirstVisible(), true);

}

public void close()
{
    // when the form closes, release the eventhandler for file upload callback
    super();
    uploadControl.notifyUploadCompleted -=  eventhandler(this.UploadCompleted);
    accessoryUpload.notifyUploadCompleted -= eventhandler(this.AccessoryUploadCompleted);
}

/// <summary> 
/// This method is called by the file upload mechanism, when the upload completes
/// </summary>
public void UploadCompleted()
{
    FileUploadTemporaryStorageResult fileUploadResult = FileUpload1.getFileUploadResult();

    if (fileUploadResult != null && fileUploadResult.getUploadStatus())
    {
        FMVehicleModel.Image = ImageReference::GetPackedBinaryData(fileUploadResult.getDownloadUrl());
    }
    else
    {
        warning("@SYS89176");
    }
}

/// <summary>
/// This method is called by the file upload mechanism, when the upload completes
/// </summary>
public void AccessoryUploadCompleted()
{
    FileUploadTemporaryStorageResult fileUploadResult = ChargeImageUpload.getFileUploadResult();

    if (fileUploadResult != null && fileUploadResult.getUploadStatus())
    {
        FMChargeType.Image = ImageReference::GetPackedBinaryData(fileUploadResult.getDownloadUrl());
    }
    else
    {
        warning("@SYS89176");
    }
}

public void executeQuery()
{
    super();

    //** Initial Positioning for FMVehicleModel Start
    if(startupFMVehicleModel)
    {                
        this.positionToRecord(startupFMVehicleModel);
        startupFMVehicleModel = null;                
    }
    //** Initial Positioning for FMVehicleModel End
}

public void clicked()
{
    FMRental rental; 

    super();

    select firstonly rental; 

    if(rental == null)
    {
        FMDataHelper::main(null);
        Box::info('@FLM:DataCreated');
    }
    else if (Box::yesNo('@FLM:DataRestoreConfirm', DialogButton::No) == DialogButton::Yes)
    {
        FMDataHelper::main(null);
        Box::info('@FLM:DataRestored');
    }
}

void clicked()
{
    FormTreeItem treeItem;

    super();

    fmVehicleModel_ds.create();
    treeItem =  makeModelTree.getItem(makeModelTree.getFirstSelected());

    fmVehicleModel.Make = treeItem.data();
}

public boolean expanding(int _idx, FormTreeExpand _action, anytype _data)
{
    boolean ret;

    element.fillMakeForParent(_idx, _data);

    ret = super(_idx, _action, _data);

    return ret;
}

public void selectionChanged(FormTreeItem _oldItem, FormTreeItem _newItem, FormTreeSelect _how)
{
    int rootIdx;
    int64 parentRecId;

    super(_oldItem, _newItem, _how);

    // Probably should use a better method to figure out type.
    rootIdx = makeModelTree.getRoot();

    if (makeModelTree.getParent(_newItem.idx()) != makeModelTree.getRoot())
    {
        make.activatePage();
        fmVehicleMake_ds.positionToRecordByValue(fieldNum(FMVehicleMake, RecId), int642str(_newItem.data()));
    }
    else
    {
        model.activatePage();

        parentRecId = makeModelTree.getItem(makeModelTree.getParent(_newItem.idx())).data();

        fmVehicleMake_ds.positionToRecordByValue(fieldNum(FMVehicleMake, RecId), int642str(parentRecId));                
    }
}
